import{_ as p,a0 as o,w as r,s as d,ao as i,I as l,x as a,a1 as t,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"ZOMBIES：如何在软件开发中实现业务需求（四） | LCTT x X-CMD","titleTemplate":false,"description":"ZOMBIES：如何在软件开发中实现业务需求（四） | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ZOMBIES：如何在软件开发中实现业务需求（四） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ZOMBIES：如何在软件开发中实现业务需求（四） | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20210204 How to implement business requirements in software development","title":"ZOMBIES：如何在软件开发中实现业务需求（四）","tag":"202305","desc":""},"relativePath":"202305/20210204 How to implement business requirements in software development.md","filePath":"[post].md"}'),u={name:"202305/20210204 How to implement business requirements in software development.md"};function g(h,s,m,b,c,f){const n=o("Link");return r(),d("div",null,[s[22]||(s[22]=i('<h1 id="zombies-如何在软件开发中实现业务需求-四" tabindex="-1">ZOMBIES：如何在软件开发中实现业务需求（四） <a class="header-anchor" href="#zombies-如何在软件开发中实现业务需求-四" aria-label="Permalink to “ZOMBIES：如何在软件开发中实现业务需求（四）”">​</a></h1><blockquote><p>完善你的电商应用，使它能够正确处理业务规则。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202305/30/094226xz66t662t42auuht.jpg" alt=""></p><p>在前面的文章中，我已经解释了为什么将编程问题看作一整群丧尸来处理是错误的。我用 ZOMBIES 方法来解释为什么循序渐进地处理问题更好。</p><p>ZOMBIES 表示以下首字母缩写：</p><ul><li><strong>Z</strong> – 最简场景（Zero）</li><li><strong>O</strong> – 单元素场景（One）</li><li><strong>M</strong> – 多元素场景（Many or more complex）</li><li><strong>B</strong> – 边界行为（Boundary behaviors）</li><li><strong>I</strong> – 接口定义（Interface definition）</li><li><strong>E</strong> – 处理特殊行为（Exercise exceptional behavior）</li><li><strong>S</strong> – 简单场景用简单的解决方案（Simple scenarios, simple solutions）</li></ul>',6)),l("p",null,[s[3]||(s[3]=a("在系列的前三篇文章中，我展示了 ZOMBIES 方法的前五项。第一篇中 ",-1)),t(n,{href:"https://linux.cn/article-15808-1.html"},{default:e(()=>[...s[0]||(s[0]=[a("实现了最简场景",-1)])]),_:1}),s[4]||(s[4]=a("，它为代码提供了最简可行路径。第二篇文章中执行了 ",-1)),t(n,{href:"https://linux.cn/article-15817-1.html"},{default:e(()=>[...s[1]||(s[1]=[a("单元素场景和多元素场景上的测试",-1)])]),_:1}),s[5]||(s[5]=a("。第三篇中介绍了 ",-1)),t(n,{href:"https://linux.cn/article-15859-1.html"},{default:e(()=>[...s[2]||(s[2]=[a("边界和接口",-1)])]),_:1}),s[6]||(s[6]=a("。在本文中，我将带你了解倒数第二个方法：处理特殊行为。",-1))]),s[23]||(s[23]=i(`<h3 id="处理特殊行为" tabindex="-1">处理特殊行为 <a class="header-anchor" href="#处理特殊行为" aria-label="Permalink to “处理特殊行为”">​</a></h3><p>在开发一个电子购物应用时，你需要从产品负责人或赞助商那里了解需要采用什么销售策略。</p><p>毫无疑问，与任何电子商业活动一样，你需要通过制定销售策略来诱导顾客进行消费。假设有如下的销售策略：订单金额超过 ￥500 时可以享受一定的折扣优惠。</p><p>现在将这个销售策略转换为可运行期望：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsTotal600GrandTotal540() {</span></span>
<span class="line"><span>        var expectedGrandTotal = 540.00;</span></span>
<span class="line"><span>        var actualGrandTotal = 0.00;</span></span>
<span class="line"><span>        Assert.Equal(expectedGrandTotal, actualGrandTotal);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个正面样例表示的销售策略是，如果订单总额为 ￥600.00，那么 <code>shoppingAPI</code> 会将其减价为 ￥540.00。上面的代码伪造了一个失败验证用例。现在修改它，让它能够通过测试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsTotal600GrandTotal540() {</span></span>
<span class="line"><span>        var expectedGrandTotal = 540.00;</span></span>
<span class="line"><span>        Hashtable item = new Hashtable();</span></span>
<span class="line"><span>        item.Add(&quot;00000001&quot;, 200.00);</span></span>
<span class="line"><span>        shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>        Hashtable item2 = new Hashtable();</span></span>
<span class="line"><span>        item2.Add(&quot;00000002&quot;, 400.00);</span></span>
<span class="line"><span>        shoppingAPI.AddItem(item2);</span></span>
<span class="line"><span>        var actualGrandTotal = shoppingAPI.CalculateGrandTotal();</span></span>
<span class="line"><span>        Assert.Equal(expectedGrandTotal, actualGrandTotal);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个正样例中，你向购物框加入一件价值 ￥200 的商品和一件价值 ￥400 的商品，使总价达到 ￥600 。当调用 <code>CalculateGrandTotal()</code> 方法时，你期望总价是 ￥540。</p><p>这个微测试能够通过吗？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[xUnit.net 00:00:00.57] tests.UnitTest1.Add2ItemsTotal600GrandTotal540 [FAIL]</span></span>
<span class="line"><span>  X tests.UnitTest1.Add2ItemsTotal600GrandTotal540 [2ms]</span></span>
<span class="line"><span>  Error Message:</span></span>
<span class="line"><span>   Assert.Equal() Failure</span></span>
<span class="line"><span>Expected: 540</span></span>
<span class="line"><span>Actual: 600</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>很可惜，它失败了。你期望的结果是 ￥540，但计算结果为 ￥600。为什么会这样呢？那是因为你还没有告诉系统在订单总价大于 ￥500 时怎么进行折扣计算。</p><p>现在来实现折扣计算逻辑。根据上面的正样例可知，当订单总价为 ￥600（超过了营销策略的阈值 ￥500）时，期望的最终总价为 ￥540。也就是说系统需要从订单总额中减去 ￥60。刚好是是原订单总价的 10%。因此该销售规则就是当订单总额超过 ￥500 时享受九折优惠。</p><p>在 <code>ShippingAPI</code> 类中实现该处理逻辑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>private double Calculate10PercentDiscount(double total) {</span></span>
<span class="line"><span>        double discount = 0.00;</span></span>
<span class="line"><span>        if(total &gt; 500.00) {</span></span>
<span class="line"><span>                discount = (total/100) * 10;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        return discount;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>首先，检查订单总额是否大于 ￥500 。如果是，则计算出总额的 10%。</p><p>你还需要告诉系统怎么从订单总额中减去 10%。改动非常直接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>return grandTotal - Calculate10PercentDiscount(grandTotal);</span></span></code></pre></div><p>到此，所有测试都能够通过。你又一次享受到系统处于稳态的欢愉。你的代码通过处理特殊行为实现了需要的销售策略。</p><h3 id="最后一步" tabindex="-1">最后一步 <a class="header-anchor" href="#最后一步" aria-label="Permalink to “最后一步”">​</a></h3><p>现在我已经介绍完 ZOMBIE 了，只剩下 S 了。我将会在最后一篇中介绍它。</p><p><em>（题图：MJ/7f8bf5d2-54ce-4d6e-9dbf-13abf6df966a）</em></p><hr>`,22)),l("p",null,[s[8]||(s[8]=a("via: ",-1)),t(n,{href:"https://opensource.com/article/21/2/exceptional-behavior"},{default:e(()=>[...s[7]||(s[7]=[a("https://opensource.com/article/21/2/exceptional-behavior",-1)])]),_:1})]),l("p",null,[s[13]||(s[13]=a("作者：",-1)),t(n,{href:"https://opensource.com/users/alex-bunardzic"},{default:e(()=>[...s[9]||(s[9]=[a("Alex Bunardzic",-1)])]),_:1}),s[14]||(s[14]=a(" 选题：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),t(n,{href:"https://github.com/toknow-gh"},{default:e(()=>[...s[11]||(s[11]=[a("toknow-gh",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[19]||(s[19]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:e(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}const C=p(u,[["render",g]]);export{x as __pageData,C as default};
